3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.repository.OwnerRepository;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.CityCapacityExceededException;
7	
8	/**
9	 * Rejects a create request whose city already holds the maximum number of owners. Runs
10	 * before {@link BuildOwner}, so a full city is a 409 via
11	 * {@link CityCapacityExceededException} before any owner is built or saved. Cities are
12	 * counted case-insensitively (see {@link Cities}).
13	 */
14	public class EnsureCityCapacity {
15	
16	    /** Maximum owners a single city may hold; the next create is rejected. */
17	    static final long MAX_OWNERS_PER_CITY = 50;
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws CityCapacityExceededException {
21	        if (Cities.countIn(ownerRepository, request.getCity()) >= MAX_OWNERS_PER_CITY) {
22	            throw new CityCapacityExceededException(request.getCity(), MAX_OWNERS_PER_CITY);
23	        }
24	    }
25	}
