1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Out;
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	
9	/**
10	 * Resolves the effective registration date for a create request and publishes it as a
11	 * variable. The effective date is the one supplied in the request, or the server's current
12	 * date when omitted; either way, a weekend is rolled forward to the next business day (see
13	 * {@link BusinessDays}). Runs before {@link EnsureDailyLimit} and {@link ApplyRegistrationDate}
14	 * so the per-day limit counts against, and the built owner is stamped with, the same adjusted
15	 * business day — and so everything derived from it (e.g. the membership-number year segment)
16	 * uses the adjusted date.
17	 */
18	public class ResolveRegistrationDate {
19	
20	    public void service(@Val OwnerFieldsDto request, Out<LocalDate> registrationDate) {
21	        LocalDate supplied = request.getRegistrationDate();
22	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
23	        registrationDate.set(BusinessDays.rollForward(effective));
24	    }
25	}
