1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.ArrayList;
7	import java.util.List;
8	import java.util.Locale;
9	
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.repository.OwnerRepository;
12	
13	/**
14	 * Identifies the owners that make up a household — those sharing a last name (compared
15	 * case-insensitively with collapsed whitespace) and a normalized address (see
16	 * {@link AddressNormalizer}). Used both to guard against accidental duplicates
17	 * ({@link EnsureUniqueHousehold}) and to group knowing house-mates under a shared,
18	 * stable household id ({@link AssignHousehold}).
19	 */
20	final class Households {
21	
22	    private Households() {
23	    }
24	
25	    /** Existing owners whose last name and address match the given household. */
26	    static List<Owner> membersAt(OwnerRepository repository, String lastName, String address) {
27	        String key = key(lastName, address);
28	        List<Owner> members = new ArrayList<>();
29	        for (Owner owner : repository.findAll()) {
30	            if (key.equals(key(owner.getLastName(), owner.getAddress()))) {
31	                members.add(owner);
32	            }
33	        }
34	        return members;
35	    }
36	
37	    /**
38	     * A stable identifier for the household with the given last name and address. Derived
39	     * from the normalized key, so every member of the same household resolves to the same
40	     * value regardless of when they are created.
41	     */
42	    static String householdId(String lastName, String address) {
43	        return "HH-" + sha256Hex(key(lastName, address)).substring(0, 24).toUpperCase(Locale.ROOT);
44	    }
45	
46	    /** The normalized last name and address joined into a single household key. */
47	    private static String key(String lastName, String address) {
48	        return normalizeName(lastName) + '\n' + AddressNormalizer.normalize(address);
49	    }
50	
51	    /** Case-fold and collapse whitespace so trivial spacing/casing differences still match. */
52	    private static String normalizeName(String value) {
53	        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
54	    }
55	
56	    private static String sha256Hex(String value) {
57	        try {
58	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
59	            StringBuilder hex = new StringBuilder(digest.length * 2);
60	            for (byte b : digest) {
61	                hex.append(String.format("%02x", b));
62	            }
63	            return hex.toString();
64	        }
65	        catch (NoSuchAlgorithmException ex) {
66	            throw new IllegalStateException("SHA-256 not available", ex);
67	        }
68	    }
69	}
