1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Shared telephone normalization for the owner pipelines: convert a raw telephone to
5	 * E.164 form. Spaces, dashes and brackets are stripped; a number that already carries
6	 * a leading {@code '+'} keeps its country code, otherwise Australian country code
7	 * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the
8	 * national digits. The result is a {@code '+'} followed by 8 to 15 digits.
9	 *
10	 * <p>Used by {@link NormalizeOwnerTelephone} (which rejects a number that cannot form
11	 * valid E.164) and by {@link EnsureUniqueTelephone} (which normalizes each stored
12	 * telephone before comparing), so the two steps agree on what "normalized" means.
13	 */
14	final class TelephoneNormalizer {
15	
16	    private TelephoneNormalizer() {
17	    }
18	
19	    /**
20	     * @return the E.164 representation of {@code telephone}, or {@code null} when it
21	     *         cannot form a valid E.164 number.
22	     */
23	    static String toE164(String telephone) {
24	        if (telephone == null) {
25	            return null;
26	        }
27	        String cleaned = telephone.replaceAll("[\\s()-]", "");
28	        String digits;
29	        if (cleaned.startsWith("+")) {
30	            digits = cleaned.substring(1);
31	        }
32	        else {
33	            if (cleaned.startsWith("0")) {
34	                cleaned = cleaned.substring(1);
35	            }
36	            digits = "61" + cleaned;
37	        }
38	        if (!digits.matches("[0-9]{8,15}")) {
39	            return null;
40	        }
41	        return "+" + digits;
42	    }
43	}
